create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, email text not null, full_name text, role text not null default 'user' check (role in ('user','commercial','admin')), utility_provider text, consumer_number text, sanctioned_load_kw numeric default 0, home_area_sqft numeric default 0, occupants integer default 0, created_at timestamptz not null default now());
create table public.electricity_bills (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, bill_number text, consumer_name text, consumer_number text, meter_number text, billing_month text, issue_date date, due_date date, units_consumed_kwh numeric not null, previous_reading numeric default 0, current_reading numeric default 0, sanctioned_load_kw numeric default 0, power_factor numeric default 0, tariff_category text, connection_type text, amount_due numeric not null, breakdown jsonb not null default '{}'::jsonb, status text default 'pending', file_url text, ocr_confidence numeric default 0, created_at timestamptz not null default now());
create table public.ocr_results (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, file_path text not null, result jsonb not null, confidence numeric, created_at timestamptz not null default now());
create table public.predictions (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, bill_id uuid references public.electricity_bills(id) on delete set null, input jsonb not null, predicted_units numeric not null, predicted_bill numeric not null, result jsonb not null, created_at timestamptz not null default now());
create table public.chat_history (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, message text not null, response text not null, model text, created_at timestamptz not null default now());
create table public.recommendations (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, bill_id uuid references public.electricity_bills(id) on delete cascade, title text not null, category text, description text, estimated_monthly_savings numeric default 0, estimated_kwh_savings numeric default 0, implementation_cost text, payback_months integer, impact_level text, status text default 'new', created_at timestamptz not null default now());
create table public.user_settings (user_id uuid primary key references public.profiles(id) on delete cascade, currency text default 'INR', unit_type text default 'kWh', alert_threshold_percent numeric default 20, email_notifications boolean default true, sms_notifications boolean default false, high_bill_alerts boolean default true, weekly_summary boolean default true, updated_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, title text not null, body text not null, kind text not null default 'info', read_at timestamptz, created_at timestamptz not null default now());
create table public.activity_logs (id uuid primary key default gen_random_uuid(), user_id uuid references public.profiles(id) on delete set null, action text not null, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.electricity_bills enable row level security; alter table public.ocr_results enable row level security; alter table public.predictions enable row level security; alter table public.chat_history enable row level security; alter table public.recommendations enable row level security; alter table public.user_settings enable row level security; alter table public.notifications enable row level security; alter table public.activity_logs enable row level security;
create policy "own profile" on public.profiles for all using (id = auth.uid()) with check (id = auth.uid());
create policy "own bills" on public.electricity_bills for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own ocr" on public.ocr_results for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own predictions" on public.predictions for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own chats" on public.chat_history for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own recommendations" on public.recommendations for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own settings" on public.user_settings for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own notifications" on public.notifications for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own activity" on public.activity_logs for select using (user_id = auth.uid());
insert into storage.buckets (id, name, public) values ('bills', 'bills', false) on conflict do nothing;
create policy "private bill storage" on storage.objects for all using (bucket_id = 'bills' and (storage.foldername(name))[1] = auth.uid()::text) with check (bucket_id = 'bills' and (storage.foldername(name))[1] = auth.uid()::text);
